    async deleteRecord(record) {
      // 弹出确认对话框
      Modal.confirm({
        title: '确认删除',
        content: '确定要删除这条记录吗？',
        onOk: async () => {
          try {
            // 设置删除按钮加载状态
            this.Deleteloading5 = true

            // 调用后端接口删除记录
            const response = await this.executeBackendInterface(
              'deleteRecord',
              {
                id: record.id,
                current: this.BillingManagementListcurrent2,
                pageSize: this.BillingManagementListpageSize1,
              }
            )

            // 检查删除操作是否成功
            if (response.flag) {
              message.success('删除成功')

              // 刷新当前表数据
              const refreshResponse = await this.executeBackendInterface(
                'getRecords',
                {
                  current: this.BillingManagementListcurrent2,
                  pageSize: this.BillingManagementListpageSize1,
                }
              )

              // 更新表数据
              if (refreshResponse.flag) {
                this.BillingManagementListdata1.dataSource =
                  refreshResponse.data.data.map((item) => ({
                    id: item.id,
                    serialNumber: item.row_index,
                    ruleNumber: item.rule_code,
                    ruleName: item.rule_name,
                    chargingstandard: item.charging_standard,
                    ruleDescription: item.rule_description,
                    numberofassociateddepots: item.associated_parking_lots,
                    creationtime: item.create_time,
                    creator1: item.create_username,
                    operation1: item.operation,
                  }))
                this.BillingManagementListtotal1 = refreshResponse.data.total
              } else {
                message.error('刷新表数据失败')
              }
            } else {
              message.error('删除失败')
            }
          } catch (error) {
            message.error('操作失败')
          } finally {
            // 取消删除按钮加载状态
            this.Deleteloading5 = false
          }
        },
        onCancel: () => {
          // 取消删除操作
        },
      })
    },
    async changeBillingScheme() {
      try {
        // 获取表单数据
        const values = await this.$refs.ref4238_form.validateFields()

        // 获取选中的收费方案类型
        const selectedScheme = values.chargingschemevalue6

        // 定义动态面板状态变量
