        // 根据选中的收费方案类型设置动态面板状态
        switch (selectedScheme) {
          case '免费停车':
            panelState = 2
            break
          case '按次收费':
            panelState = 3
            break
          case '自然天收费':
            panelState = 4
            break
          case '分段收费':
            panelState = 5
            break
          case '节假日/工作日不同费用':
            panelState = 6
            break
          default:
            panelState = 1
