    loadCss('./css/计费管理/theme.css')
    this.initBillingManagementList()
    this.initOperationRecords()
    this.fetchAssociatedParkingLots()
    // 组件挂载后自动调用函数获取变量
    this.fetchAndSetVariables()
  },
